use std::{fs,path::{Path,PathBuf}};
use serde_json::Value;
fn audio_dialog()->Option<PathBuf>{rfd::FileDialog::new().set_title("Locate original recording").add_filter("Audio",&["wav","mp3","m4a","aac","flac","ogg","opus","aiff","aif","wma"]).pick_file()}
#[tauri::command]
pub async fn locate_project_audio(name:String,fingerprint:Option<String>)->Result<Option<String>,String>{tauri::async_runtime::spawn_blocking(move||{
 let folder=rfd::FileDialog::new().set_title("Choose a folder to search for the missing recording").pick_folder();let Some(folder)=folder else{return Ok(None)};let mut dirs=vec![(folder,0)];let mut matches=Vec::<PathBuf>::new();let mut count=0;
 while let Some((dir,depth))=dirs.pop(){if depth>32{return Err("Choose a less deeply nested folder".into());}for e in fs::read_dir(dir).map_err(|e|e.to_string())?.flatten(){count+=1;if count>20000{return Err("Choose a smaller folder to search".into());}let k=e.file_type().map_err(|e|e.to_string())?;if k.is_symlink(){continue;}if k.is_dir(){if e.file_name()!="Studio Link"{dirs.push((e.path(),depth+1));}}else if k.is_file()&&crate::audio_identity::supported(&e.path())&&e.file_name().to_string_lossy().eq_ignore_ascii_case(&name){if let Ok(info)=crate::audio_identity::info(&e.path()){if fingerprint.as_deref().is_none_or(|fp|info["fingerprint"].as_str()==Some(fp)){matches.push(e.path());}}}}}
 let path=if matches.len()==1{matches.pop()}else{audio_dialog()};Ok(path.map(|p|p.to_string_lossy().into_owned()))
 }).await.map_err(|e|e.to_string())?}
#[tauri::command]
pub async fn recover_subtitler_audio(directory:Option<String>,project_id:String,fingerprint:Option<String>,document_path:Option<String>)->Result<Option<String>,String>{tauri::async_runtime::spawn_blocking(move||{
 let root=crate::studio_files::root(directory.as_deref().ok_or("Choose or locate the project folder first")?)?;let manifest:Value=serde_json::from_slice(&fs::read(crate::studio_files::local_file(&root,"Studio Link/project.json")?).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if manifest["project"]["id"]!=project_id{return Err("This folder belongs to another project".into());}
 let mut document=document_path.map(PathBuf::from).filter(|p|p.is_file());if document.is_none(){if let Ok(bytes)=fs::read(root.join("Studio Link/subtitler-files.json")){if let Ok(registry)=serde_json::from_slice::<Value>(&bytes){if let Some(fp)=fingerprint.as_deref(){document=registry["recordings"][fp]["path"].as_str().map(PathBuf::from).filter(|p|p.is_file());}}}}
 if document.is_none(){document=rfd::FileDialog::new().set_title("Choose the Subtitler project containing this recording").add_filter("Subtitler project",&["subtitler"]).pick_file();}let Some(document)=document else{return Ok(None)};let data=crate::audio_package::read(&document)?;if data.project["studioLink"]["projectId"].as_str().is_some_and(|id|id!=project_id){return Err("This Subtitler file is connected to another project".into());}
 let name=Path::new(data.audio["name"].as_str().unwrap_or("Recovered audio.wav")).file_name().ok_or("Invalid embedded audio name")?.to_string_lossy().into_owned();let mut output=root.join(&name);
 if output.exists(){let actual=crate::audio_identity::info(&output)?;if actual["fingerprint"]!=data.audio["fingerprint"]{let p=Path::new(&name);let stem=p.file_stem().unwrap_or_default().to_string_lossy();let ext=p.extension().unwrap_or_default().to_string_lossy();let mut found=None;for i in 1..10000{let candidate=root.join(format!("{stem} - recovered {i}.{ext}"));if !candidate.exists(){found=Some(candidate);break;}}output=found.ok_or("Choose another recovery location")?;}}
 crate::audio_package::extract(&document,&output,fingerprint.as_deref())?;Ok(Some(output.to_string_lossy().into_owned()))
 }).await.map_err(|e|e.to_string())?}
